const title = String(run.display_title || run.name || '');
const m = title.match(/qa-pr\s+([A-Z][A-Z0-9]+-\d+)\s+\[([^\]]+)\]/);
const branchKey = String(run.head_branch || '').match(/^qa\/([A-Z][A-Z0-9]+-\d+)$/);
