      items: {
        type: 'object', required: ['signature', 'category', 'confidence', 'tests', 'evidence', 'action'],
        props: {
          category: { type: 'string', enum: CATS },
          confidence: { type: 'number', min: 0, max: 1 },
          tests: { type: 'array', minItems: 1, items: { type: 'object', required: ['title'] } },
